        if(oxygenLevel < PLANT_OXYGEN_REQUIRED){
            setDead();
            return 0;
        }    


        if(isAlive()){
            if(age >= MATURE_AGE)
                giveBirth(newSeaweeds);            
            }


        if(atDayTime)
            return OXYGEN_GENERATED;
        else
            return -PLANT_OXYGEN_REQUIRED;
        }

    /**
